import {buildStreetDetail,createStreetMaterials} from './geo-street-detail.js';
import {focus,inFocus} from './geo-xinyi-detail.js';
// OSM coordinates are retained. Widths without tags are explicitly estimates.
export const metres=(a,b)=>Math.hypot((b[0]-a[0])*111320*Math.cos(a[1]*Math.PI/180),(b[1]-a[1])*110574);
export function pointAlong(path,distance){let remaining=Math.max(0,distance);for(let i=1;i<path.length;i++){const a=path[i-1],b=path[i],length=metres(a,b);if(remaining<=length||i===path.length-1){const t=length?Math.min(1,remaining/length):0;return {longitude:a[0]+(b[0]-a[0])*t,latitude:a[1]+(b[1]-a[1])*t,heading:(Math.atan2((b[0]-a[0])*Math.cos(a[1]*Math.PI/180),b[1]-a[1])*180/Math.PI+360)%360};}remaining-=length;}return null;}
export const pathLength=path=>path.slice(1).reduce((sum,p,i)=>sum+metres(path[i],p),0);
export async function createStreets({view,map,Graphic,GraphicsLayer,Point,Multipoint,Mesh,Material,getPlace,onSurfaceChange=()=>{}}){
 const layer=new GraphicsLayer({title:'真實路網・路面與人行路徑',elevationInfo:{mode:'relative-to-ground'},minScale:18000});map.add(layer,1);
 const detailLayer=new GraphicsLayer({title:'信義中心街道・細部材質',elevationInfo:{mode:'absolute-height'},minScale:18000,popupEnabled:false});map.add(detailLayer,2);const materials=createStreetMaterials(Material);const drapeLayer=new GraphicsLayer({title:'信義街道・地形貼合鋪面',elevationInfo:{mode:'on-the-ground'},minScale:18000,popupEnabled:false});map.add(drapeLayer,2);
 const cache={},panel=document.getElementById('streets');let renderedSurface=null,renderTask=Promise.resolve(),reviewMode=false,waitingMode=false;let token=0,current=null,selected=null,along=0,moving=false;
 panel.innerHTML='<h2>街道近看</h2><label class="street-toggle"><input id="streetVisible" type="checkbox" checked> 顯示路面與人行路徑</label><label class="street-toggle" id="streetRenderControl"><input id="streetRender" type="checkbox" checked> 信義中心街道・瀝青與鋪面材質</label><p id="streetRenderStatus" role="status"></p><button id="songzhiRenderView">看松智路渲染</button><p id="streetStatus" role="status">正在載入路網…</p><label for="streetSelect">選擇街道</label><select id="streetSelect"></select><button id="streetView">沿街近看</button><div class="deploy-row"><button id="streetBack">沿街後移</button><button id="streetNext">沿街前移</button></div><p id="streetDetail"></p><details><summary>路面資料與精度</summary><p>位置來自 OpenStreetMap 實際路網。深灰為車行路面、淺灰為人行路徑；僅已標記的人行道呈現高差。材質與人行道高度為視覺示意。</p><p>缺少 width 的路段依車道數或道路類型使用示意寬度，不能據此量測淨寬或判定支腿空間。中心約 250 公尺的瀝青顆粒、鋪面接縫與人行道路緣為示意材質，未逐點現勘；沿用原路網及寬度。未增畫缺乏依據的車道線或未標記人行道；斑馬線另依 OSM 明確 zebra 標記製作尺寸示意；橋梁、地下及室內路徑未轉成地面道路。</p><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors · ODbL</a></details>';
 const $=id=>document.getElementById(id),status=t=>{$('streetStatus').textContent=t;};
 const controls=()=>{for(const id of ['streetView','streetBack','streetNext','streetSelect'])$(id).disabled=moving||!selected;};
 function choose(){selected=current?.features.find(f=>String(f.id)===$('streetSelect').value)||null;along=selected?pathLength(selected.paths[0])/2:0;controls();$('streetDetail').textContent=selected?(selected.tags.name||'未命名路徑')+' · '+(selected.widthSource==='tag'?'OSM 標記寬度 ':'示意寬度 ')+selected.width.toFixed(1)+' m':'';}
 $('streetSelect').onchange=choose;$('streetVisible').onchange=()=>{layer.visible=$('streetVisible').checked;detailLayer.visible=layer.visible&&$('streetRender').checked&&getPlace()==='xinyi';drapeLayer.visible=detailLayer.visible;onSurfaceChange();};
 async function move(step){if(!selected||moving)return;const ticket=token;moving=true;controls();try{const path=selected.paths[0];along=Math.max(0,Math.min(pathLength(path),along+step));const p=pointAlong(path,along);const elevation=await map.ground.queryElevation(new Point({...p,spatialReference:{wkid:4326}}));if(ticket!==token)return;if(!Number.isFinite(elevation.geometry.z))throw Error('地面高度尚未載入');await view.goTo({position:{longitude:p.longitude,latitude:p.latitude,z:elevation.geometry.z+3.2},heading:p.heading,tilt:82},{animate:false});status('沿街視角 · '+(selected.tags.name||'人行路徑')+' · 可右鍵拖曳轉向');}catch(error){if(ticket===token&&error.name!=='AbortError')status('街道視角定位失敗，請待地形載入後重試。');}finally{moving=false;controls();}}
 $('streetView').onclick=()=>move(0);$('streetBack').onclick=()=>move(-15);$('streetNext').onclick=()=>move(15);
 async function changePlace(){const ticket=++token;current=null;selected=null;renderedSurface=null;layer.removeAll();detailLayer.removeAll();drapeLayer.removeAll();$('streetSelect').replaceChildren();$('streetDetail').textContent='';controls();const place=getPlace();$('streetRenderControl').hidden=place!=='xinyi';$('songzhiRenderView').hidden=place!=='xinyi';$('songzhiRenderView').disabled=true;$('streetRenderStatus').textContent='';detailLayer.visible=place==='xinyi'&&layer.visible&&$('streetRender').checked;drapeLayer.visible=detailLayer.visible;if(!['xinyi','ximen'].includes(place)){status('切換信義或西門可使用街道近看。');return;}status('正在載入真實路網…');try{const data=cache[place]||await fetch('assets/streets-'+place+'.json').then(r=>{if(!r.ok)throw Error('街道資料下載失敗');return r.json();});cache[place]=data;if(ticket!==token)return;current=data;
  const graphics=[];for(const f of data.features){const walk=['sidewalk','walk'].includes(f.kind),raised=f.kind==='sidewalk',height=raised?.12:.025;graphics.push(new Graphic({geometry:{type:'polyline',paths:f.paths,spatialReference:{wkid:4326}},symbol:{type:'line-3d',symbolLayers:[{type:'path',profile:'quad',width:f.width,height,anchor:'bottom',cap:'butt',join:'round',profileRotation:'heading',castShadows:false,material:{color:place==='xinyi'&&f.paths.some(path=>path.some(p=>inFocus(p[0],p[1])))?(walk?'#b9b6ab':f.kind==='cycle'?'#657f79':'#30363a'):(walk?'#aaa99f':f.kind==='cycle'?'#657f79':'#41474b')}}]},attributes:{name:f.tags.name||'未命名路徑',kind:f.tags.highway,width:f.width,widthSource:f.widthSource==='tag'?'OSM 標記值':'示意值（非實測）',osmId:String(f.id)},popupTemplate:{title:'{name}',content:[{type:'fields',fieldInfos:[{fieldName:'kind',label:'道路類型'},{fieldName:'width',label:'呈現寬度（m）'},{fieldName:'widthSource',label:'寬度依據'},{fieldName:'osmId',label:'OSM 路段編號'}]}]}}));}
  layer.addMany(graphics);onSurfaceChange();if(place==='xinyi')renderTask=renderDetail(data,ticket);applyReviewMode();const streets=data.features.filter(f=>f.tags.name&&f.paths[0].length>1).sort((a,b)=>a.tags.name.localeCompare(b.tags.name,'zh-TW'));for(const f of streets){const o=document.createElement('option');o.value=f.id;o.textContent=f.tags.name+' · 路段 '+f.id;$('streetSelect').append(o);}if(place==='xinyi'){const nearby=streets.map(f=>({f,p:pointAlong(f.paths[0],pathLength(f.paths[0])/2)})).filter(({f,p})=>p&&inFocus(p.longitude,p.latitude)&&!['walk','sidewalk','cycle'].includes(f.kind)).sort((a,b)=>metres([a.p.longitude,a.p.latitude],[focus.longitude,focus.latitude])-metres([b.p.longitude,b.p.latitude],[focus.longitude,focus.latitude]));if(nearby.length)$('streetSelect').value=String(nearby[0].f.id);}choose();$('songzhiRenderView').disabled=place!=='xinyi';status((place==='xinyi'?'信義':'西門')+'：'+data.features.length+' 段路徑 · '+data.features.filter(f=>f.widthSource==='tag').length+' 段有寬度標記');
 }catch(error){if(ticket===token)status('路面資料未能載入，保留原底圖；請重新整理再試。');}}
 async function renderDetail(data,ticket){
  $('streetRenderStatus').textContent='正在渲染中心街道材質…';
  try{const detail=buildStreetDetail(data.features);if(!detail.position.length)return;
   for(const [kind,faces] of Object.entries(detail.groups)){if(kind==='curb'||!faces.length)continue;const rings=[];for(let i=0;i<faces.length;i+=6){const start=faces[i]*3;const ring=[];for(let k=0;k<4;k++)ring.push(detail.position.slice(start+k*3,start+k*3+2));ring.push([...ring[0]]);rings.push(ring);}drapeLayer.add(new Graphic({geometry:{type:'polygon',rings,spatialReference:{wkid:4326}},symbol:{type:'polygon-3d',symbolLayers:[{type:'fill',material:{color:{asphalt:'#3a3c3d',pavers:'#b1b1aa',concrete:'#a6a8a6',cycle:'#49605a'}[kind]}}]}}));}
   const points=[];for(let i=0;i<detail.position.length;i+=3)points.push([detail.position[i],detail.position[i+1],0]);
   const sampled=await map.ground.queryElevation(new Multipoint({points,spatialReference:{wkid:4326}}),{returnSampleInfo:true});
   if(ticket!==token)return;
   const ground=sampled.geometry.points;if(ground.length!==points.length||sampled.sampleInfo?.some(s=>s.demResolution<0))throw Error('地形取樣未完成');
   for(let i=0;i<ground.length;i++){if(!Number.isFinite(ground[i][2]))throw Error('地形高度缺失');detail.position[i*3+2]+=ground[i][2];}
   renderedSurface=detail;const mesh=new Mesh({spatialReference:{wkid:4326},vertexSpace:{type:'georeferenced'},vertexAttributes:{position:new Float64Array(detail.position),normal:new Float32Array(Array.from({length:detail.position.length},(_,i)=>i%3===2?1:0)),uv:new Float32Array(detail.uv)},components:Object.entries(detail.groups).filter(([,f])=>f.length).map(([kind,faces])=>({faces:new Uint32Array(faces),material:materials[kind],shading:'flat'}))});
   detailLayer.add(new Graphic({geometry:mesh,symbol:{type:'mesh-3d',symbolLayers:[{type:'fill'}]}}));
   $('streetRenderStatus').textContent='中心 '+detail.paths+' 段路徑已加入瀝青、鋪面與路緣材質；樣式為示意，寬度沿用原資料。';
  }catch(e){if(ticket===token){detailLayer.removeAll();$('streetRenderStatus').textContent='地形貼合鋪面已保留，細部材質未完成；可重新整理再試。';}console.error(e);}
 }
 function applyReviewMode(){for(const g of layer.graphics)g.visible=!(reviewMode&&$('streetRender').checked&&(g.attributes.osmId==='1335559368'||waitingMode&&['1335559364','1335559369'].includes(g.attributes.osmId)));}
 $('streetRender').onchange=()=>{applyReviewMode();detailLayer.visible=$('streetRender').checked&&layer.visible&&getPlace()==='xinyi';drapeLayer.visible=detailLayer.visible;};
 $('songzhiRenderView').onclick=async()=>{if(getPlace()!=='xinyi'||moving)return;moving=true;controls();try{const longitude=121.56544,latitude=25.03440;const e=await map.ground.queryElevation(new Point({longitude,latitude,spatialReference:{wkid:4326}}));if(!Number.isFinite(e.geometry.z))throw Error('高度缺失');await view.goTo({position:{longitude,latitude,z:e.geometry.z+3.2},heading:0,tilt:82},{animate:false});}catch(e){if(e.name!=='AbortError')status('松智路視角未完成，請重新操作。');}finally{moving=false;controls();}};
 function surfaceHeight(point){if(!current||!layer.visible)return 0;let height=0;const c=Math.cos(point.latitude*Math.PI/180);for(const f of current.features){for(const path of f.paths)for(let i=1;i<path.length;i++){const a=[(path[i-1][0]-point.longitude)*111320*c,(path[i-1][1]-point.latitude)*110574],b=[(path[i][0]-point.longitude)*111320*c,(path[i][1]-point.latitude)*110574],dx=b[0]-a[0],dy=b[1]-a[1],den=dx*dx+dy*dy,t=den?Math.max(0,Math.min(1,-(a[0]*dx+a[1]*dy)/den)):0;if(Math.hypot(a[0]+t*dx,a[1]+t*dy)<=f.width/2)height=Math.max(height,f.kind==='sidewalk'?.12:.025);}}return height;}
 await changePlace();return {changePlace,surfaceHeight,getRenderedSurface:async()=>{await renderTask;return renderedSurface;},setLaneReview:(enabled,waiting=false)=>{reviewMode=enabled;waitingMode=waiting;applyReviewMode();}};
}
